11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // project references client via FK; H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the duration of the clear, then restore it.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE dashboard_config");
39	        jdbc.execute("TRUNCATE TABLE note RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE project_tag RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE tag RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE task RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE payment RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE client_payment RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE line_item RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE invoice RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE project RESTART IDENTITY");
48	        jdbc.execute("TRUNCATE TABLE contact RESTART IDENTITY");
49	        jdbc.execute("TRUNCATE TABLE client RESTART IDENTITY");
50	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
51	    }
52	
53	    /**
54	     * Parse a seeded timestamp, tolerating both a full ISO-8601 instant ({@code 2026-02-01T09:00:00Z})
55	     * and a bare date ({@code 2026-02-01}, taken at the start of the day in UTC).
56	     */
57	    private static java.time.Instant parseInstant(String value) {
58	        if (value.length() == 10) {
59	            return java.time.LocalDate.parse(value).atStartOfDay(java.time.ZoneOffset.UTC).toInstant();
60	        }
61	        return java.time.Instant.parse(value);
62	    }
63	
64	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
65	    @PostMapping("/seed")
66	    @SuppressWarnings("unchecked")
67	    public void seed(@RequestBody Map<String, Object> fixture) {
68	        Object asOf = fixture.get("asOf");
69	        if (asOf != null) {
70	            // The dashboard's reference date for deciding which SENT invoices are overdue (V24).
71	            jdbc.update("INSERT INTO dashboard_config (id, as_of) VALUES (1, ?)",
72	                    java.sql.Date.valueOf(asOf.toString()));
73	        }
74	        List<Map<String, Object>> clients =
75	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
76	        for (Map<String, Object> client : clients) {
77	            boolean archived = Boolean.TRUE.equals(client.getOrDefault("archived", Boolean.FALSE));
78	            jdbc.update("INSERT INTO client (id, name, email, archived) VALUES (?, ?, ?, ?)",
79	                    ((Number) client.get("id")).longValue(), client.get("name"), client.get("email"),
80	                    archived);
81	        }
82	        List<Map<String, Object>> projects =
83	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
84	        for (Map<String, Object> project : projects) {
